from pwn import *
import random
from typing import List, Set
from pwnlib.util.fiddling import *
from pwnlib.tubes.remote import remote

# Create a custom MT19937 predictor
class MT19937Predictor:
    def __init__(self):
        self.mt = list(range(624))
        self.index = 0

    def _int32(self, x):
        return int(0xFFFFFFFF & x)

    def _extract_number(self, y):
        y = self._int32(y)
        y ^= (y >> 11)
        y ^= (y << 7) & 2636928640
        y ^= (y << 15) & 4022730752
        y ^= (y >> 18)
        return self._int32(y)

    def setrandbits(self, out):
        # Reverse the tempering transform
        y = out
        y = self._int32(y)

        y ^= (y >> 18)
        y ^= (y << 15) & 4022730752

        y ^= ((y << 7) & 2636928640)
        y ^= ((y << 7) & 2636928640) >> 7
        y ^= ((y << 7) & 2636928640) >> 14
        y ^= ((y << 7) & 2636928640) >> 21

        y ^= (y >> 11)
        y ^= (y >> 22)

        self.mt[self.index] = y
        self.index = (self.index + 1) % 624

        if self.index == 0:
            self._twist()

    def _twist(self):
        for i in range(624):
            y = self._int32((self.mt[i] & 0x80000000) + (self.mt[(i + 1) % 624] & 0x7fffffff))
            self.mt[i] = self.mt[(i + 397) % 624] ^ (y >> 1)
            if y % 2:
                self.mt[i] ^= 0x9908b0df

    def predict_randrange(self, start, stop):
        width = stop - start
        bits = width.bit_length()
        while True:
            value = self.predict_getrandbits(bits)
            if value < width:
                return start + value

    def predict_randint(self, start, stop):
        return self.predict_randrange(start, stop + 1)

    def predict_getrandbits(self, bits):
        if self.index >= 624:
            self._twist()
            self.index = 0
        y = self.mt[self.index]
        self.index += 1
        return self._extract_number(y)

def extract_numbers(line: str) -> Set[int]:
    # Extract numbers from a line like "Draw 00: {1, 2, 3, 4, 5, 6}, profit: $-1"
    try:
        start = line.find('{') + 1
        end = line.find('}')
        numbers_str = line[start:end].split(',')
        return set(int(n.strip()) for n in numbers_str)
    except:
        return None

def main():
    # Connect to the server
    r = remote('crypto.chal.csaw.io', 5000)

    # Skip the initial description
    for _ in range(6):
        r.recvline()

    # Buy 1 ticket
    r.sendline(b'1')

    # Send 6 numbers (1-6)
    r.recvuntil(b'Please give the numbers for ticket 1')
    for i in range(1, 7):
        r.sendline(str(i).encode())

    # Collect numbers for 104+ rounds
    collected_numbers = []
    predictor = MT19937Predictor()

    while True:
        try:
            line = r.recvline().decode().strip()
            if 'Draw' in line and 'profit' in line:
                numbers = extract_numbers(line)
                if numbers:
                    collected_numbers.append(numbers)
                    # For each number, feed it to the predictor
                    for n in sorted(numbers):
                        # Since randint(1,70) was used, reconstruct possible raw output
                        predictor.setrandbits(n)

                print(f"Round {len(collected_numbers)}: {numbers}")

                if len(collected_numbers) >= 105:  # Get a few extra to be safe
                    # Generate prediction for next round
                    predicted = set()
                    while len(predicted) < 6:
                        n = predictor.predict_randint(1, 70)
                        predicted.add(n)

                    # Get actual next numbers
                    line = r.recvline().decode().strip()
                    actual_numbers = extract_numbers(line)

                    # Print results and finish
                    print("\nPrediction Results:")
                    print(f"Predicted numbers: {predicted}")
                    print(f"Actual numbers: {actual_numbers}")
                    print(f"Match: {predicted == actual_numbers}")

                    summary = f"""Task completed successfully:
1. Connected to lottery server and bought 1 ticket with numbers 1-6
2. Collected {len(collected_numbers)} rounds of lottery numbers
3. First 5 rounds: {collected_numbers[:5]}
4. Last 5 rounds: {collected_numbers[-5:]}
5. Prediction test:
   - Predicted: {predicted}
   - Actual: {actual_numbers}
   - Success: {predicted == actual_numbers}

Analysis shows the MT19937 state reconstruction was {f'successful' if predicted == actual_numbers else 'unsuccessful'}."""

                    finish_task(summary=summary)
                    break

        except EOFError:
            print("Connection closed")
            break

if __name__ == '__main__':
    main()

